public sealed record PostSummary(int Id, string Title);

public static class PostQueries
{
    public static async Task<IReadOnlyList<PostSummary>> GetPostsWithTitlePrefixAsync(
        BlogContext context,
        string prefix,
        CancellationToken cancellationToken = default)
    {
        var allPostsQuery =
            from post in context.Posts
            select new PostSummary(post.Id, post.Title);

        var allPostSummaries = await allPostsQuery.ToListAsync(cancellationToken);

        var matchingQuery =
            from summary in allPostSummaries
            where TitleRules.HasPrefix(summary.Title, prefix)
            select summary;

        return matchingQuery.ToList();
    }
