public static class PostRetitler
{
    public static async Task<bool> RenamePostAsync(
        BlogContext context,
        int postId,
        string newTitle,
        CancellationToken cancellationToken)
    {
        var postQuery =
            from post in context.Posts
            where post.Id == postId
            select post;

        var loadedPost = await postQuery.SingleOrDefaultAsync(cancellationToken);

        if (loadedPost is null)
        {
            return false;
        }

        loadedPost.Title = newTitle;
        await context.SaveChangesAsync(cancellationToken);
        return true;
    }
}
